function byId(i){for(var k=0;k<SITES.length;k++){if(SITES[k].id===i)return SITES[k]}return null}
function hostOf(u){var m=String(u).match(/^https?:\/\/([^\/]+)/);return m?m[1].toLowerCase():''}
function tagOf(u){var i=String(u).indexOf('#');return i<0?'':String(u).substring(i+1)}
function siteOf(u){var t=tagOf(u);if(t){var s=byId(t);if(s)return s}var h=hostOf(u);if(!h)return null;for(var k=0;k<SITES.length;k++){if(hostOf(SITES[k].base)===h)return SITES[k]}return null}
function strip(u){var i=String(u).indexOf('#');return i<0?String(u):String(u).substring(0,i)}
function abs(b,u){if(!u)return'';u=String(u).replace(/^\s+|\s+$/g,'');if(u.indexOf('http')===0)return u;if(u.charAt(0)==='/')return b+u;return b+'/'+u}
function firstLine(u){var a=String(u||'').split('\n');for(var i=0;i<a.length;i++){if(a[i].replace(/\s/g,''))return a[i].replace(/^\s+|\s+$/g,'')}return''}
function ruleOf(r){
  if(r&&(r.charAt(0)==='-'||r.charAt(0)==='+'))return r.substring(1);
  return r;
}
function reversed(r){return !!r&&r.charAt(0)==='-'}
function pick(J,rule,el){if(!rule)return'';try{return el?String(J.getString(rule,el)):String(J.getString(rule))}catch(e){return''}}
function pickUrl(J,rule,el){return firstLine(pick(J,rule,el))}

function fill(u,kw,page){
  u=String(u).replace(/\{\{key\}\}/g,encodeURIComponent(kw)).replace(/\{\{page\}\}/g,String(page||1));
  return u;
}
function itemOf2(J,s,r,el){
  var url=abs(s.base,pickUrl(J,r.bookUrl,el));
  if(!url)return null;
  return {n:pick(J,r.name,el),u:url,a:pick(J,r.author,el),c:abs(s.base,pickUrl(J,r.coverUrl,el))};
}
function grab(J,s,r){
  var els=J.getElements(ruleOf(r.bookList)),arr=[];
  for(var j=0;j<els.size();j++){var x=itemOf2(J,s,r,els.get(j));if(x)arr.push(x)}
  if(reversed(r.bookList))arr.reverse();
  return arr;
}
function itemOf(J,s,el,id){
  if(s.kind==='api'){
    var v=el;
    if(!v||!v.vod_id)return null;
    return {n:String(v.vod_name||''),u:s.base+'/api.php/provide/vod/?ac=detail&ids='+v.vod_id,
            a:String(v.vod_remarks||''),c:String(v.vod_pic||''),k:String(v.type_name||'')};
  }
  var url=abs(s.base,pickUrl(J,s.s.bookUrl,el));
  if(!url)return null;
  return {n:pick(J,s.s.name,el),u:url,a:pick(J,s.s.author,el),c:abs(s.base,pickUrl(J,s.s.coverUrl,el))};
}

function listFrom(J,s,body,mode){
  if(mode==='explore'&&s.kind!=='api'){
    var r0=grab(J,s,s.s);
    if(!r0.length&&s.alt){for(var q=0;q<s.alt.length&&!r0.length;q++)r0=grab(J,s,s.alt[q]);}
    return r0;
  }
  if(s.kind==='api'){
    var L=null;
    try{L=JSON.parse(String(body))}catch(e){return[]}
    if(!L||!L.list)return[];
    var out=[];
    for(var i=0;i<L.list.length&&i<20;i++){var it=itemOf(J,s,L.list[i],i);if(it)out.push(it)}
    return out;
  }
  var rl=s.s.bookList;var els=J.getElements(ruleOf(rl)),out2=[];
  for(var j=0;j<els.size();j++){var e=els.get(j);var x=itemOf(J,s,e,j);if(x)out2.push(x)}
  if(reversed(rl))out2.reverse();
  return out2;
}

function apiInfo(J,body,field){
  try{var L=JSON.parse(String(body)).list[0];return String(L[field]||'')}catch(e){return ''}
}
function contentOf(J,base){
  var s=siteOf(base);
  if(!s)return String(base);
  if(s.kind==='api')return String(base);
  var r=s.c&&s.c.content;
  if(r&&String(r).indexOf('hook:bcs')===0)return bcsContent(J,base);
  return pick(J,r);
}
// 八叉书库正文由 /conapi.php 异步下发，页面里只有一段内联参数对象。
// 参数 t 是裸数字，按带引号的字符串去匹配会取空，接口随即回「访问异常」。
// 八叉书库正文由 /conapi.php 异步下发，页面里只有一段内联参数对象。
// 参数 t 是裸数字，按带引号的字符串去匹配会取空，接口随即回「访问异常」。
function bcsContent(J,base){
  try{
    var html=String(J.ajax(base));
    var keys=['url','mobile','isk','novel','chapter','t','n','sign'];
    var vals={};
    var i,k,m;
    for(i=0;i<keys.length;i++){
      k=keys[i];
      m=html.match(new RegExp('"'+k+'"\\s*:\\s*"([^"]*)"'));
      if(m){vals[k]=m[1];}
      else{
        m=html.match(new RegExp('"'+k+'"\\s*:\\s*([^,\\s}]+)'));
        vals[k]=m?String(m[1]).replace(/"/g,''):'';
      }
    }
    if(!vals.url||!vals.sign){return '';}
    var parts=[],kk;
    for(kk in vals){
      if(vals.hasOwnProperty(kk)){parts.push(kk+'='+encodeURIComponent(vals[kk]));}
    }
    var hd={};
    hd['User-Agent']='Mozilla/5.0 (Linux; U; Android 10) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/100.0.4896.58 Mobile Safari/537.36';
    hd['Accept']='application/json, text/javascript, */*; q=0.01';
    hd['x-requested-with']='XMLHttpRequest';
    hd['content-type']='application/x-www-form-urlencoded; charset=UTF-8';
    hd['origin']='https://bcshuku.com';
    hd['referer']=base;
    var resp=J.post('https://bcshuku.com/conapi.php',parts.join('&'),hd);
    var txt=String(resp.body?resp.body():resp);
    J.log('BCS-RESP:'+txt.substring(0,100));
    var obj=JSON.parse(txt);
    if(!obj||String(obj.success)==='0'||!obj.content){return '';}
    return String(obj.content).replace(/<br\s*\/?>/gi,'\n').replace(/&nbsp;/g,' ');
  }catch(e){J.log('BCS-FAIL: '+e);return '';}
}
function searchAll(J,kw,page){
  var out=[];
  for(var k=0;k<SITES.length;k++){
    var s=SITES[k];
    if(!s.search&&!s.post)continue;
    try{
      var html=String(J.ajax(s.post?fill(s.post,kw,page):abs(s.base,fill(s.search,kw,page))));
      J.setContent(html,s.base);
      var rows=listFrom(J,s,html);
      for(var i=0;i<rows.length&&i<20;i++)out.push(rows[i]);
    }catch(e){J.log('['+s.id+'] 搜索失败: '+e)}
  }
  return out;
}
function exploreAll(J){
  var out=[];
  // 发现页只由一个目录源驱动：它提供分类与榜单，列表尽量完整。
  // 其余站点不参与发现页，只负责搜索和正文，避免同类列表混入多个站的排版与缺章。
  for(var k=0;k<SITES.length;k++){
    var s=SITES[k];
    if(!s.cat)continue;
    if(s.e){
      for(var i=0;i<s.e.length;i++){
        var e=s.e[i];
        out.push({title:e.t,url:abs(s.base,e.u)+'#'+s.id,rank:e.r||''});
      }
    }
    if(s.rk){
      for(var j=0;j<s.rk.length;j++){
        var r=s.rk[j];
        out.push({title:r.t,url:abs(s.base,r.u)+'#'+s.id,rank:r.r||''});
      }
    }
  }
